custom_css:
/*
 * 黑白棋子 · 夜间
 * 基于 KAKAA 的双色盒子框架二改
 * 原作者：KAKAA | Discord: @rech0_viixi
 * 许可协议：CC BY-NC-SA 4.0
 * 二改分享需注明原作者
 * 禁止任何形式的商用及商用目的的引流！
 */

/* ！！！---全局---！！！ */
/* 主题色配置 */
:root {
  --theme-color-1: var(--SmartThemeQuoteColor);
  --theme-color-2: var(--SmartThemeUnderlineColor);
  --ui-color-main: var(--SmartThemeBlurTintColor);
  --ui-color-sec: color-mix(
    in srgb,
    var(--ui-color-main) 88%,
    var(--text-color-main)
  );
  --top-bar-color: var(--SmartThemeBorderColor);
  --top-bar-underline-color: var(--theme-color-1);
  --top-bar-icon-color: var(--text-color-main);
  --chat-background-color: var(--SmartThemeChatTintColor);
  --text-color-main: var(--SmartThemeBodyColor);
  --text-color-sec: var(--SmartThemeEmColor);
  --user-color: var(--SmartThemeUserMesBlurTintColor);
  --char-color: var(--SmartThemeBotMesBlurTintColor);
  --code-color: var(--SmartThemeShadowColor);
  --gradient-main: linear-gradient(
    135deg,
    var(--theme-color-1) 30%,
    color-mix(in srgb, var(--theme-color-1) 50%, var(--theme-color-2) 50%) 50%,
    var(--theme-color-2) 70%
  );

  /* 棋子主题专属变量 - 夜间 */
  --chess-white: #d7d4d0;
  --chess-black: #121110;
  --chess-gray: #5a5856;
  --chess-line: #3a3836;
  --chess-accent: #8a8882;
  --chess-glow: rgba(215, 212, 208, 0.08);
}

:root {
  --mes-width: 100%;
  --mes-block-width: 98%;
  --box-border-radius: 0px;
  --top-distance: 0px;
  --bottom-distance: 0px;
  --chat-send-spacing: 0px;
  --leftRight-chat-spacing: 0px;
  --scroll-width: 0px;
  --icon-size: var(--mainFontSize);
  --border-radius-small: 5px;
  --border-radius-medium: 10px;
  --spacing-long: 10px;
  --spacing-short: 5px;
  --topBarIconSize: calc(var(--icon-size) * 2);
}

* {
    scrollbar-width: thin !important;  
}
/* ---标题--- */

/* 标题装饰 */
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content > h3,
.drawer-content
  .flex-container
  h3:first-of-type:not(#Backgrounds .textAlignCenter),
.drawer-content .flex-container .flex-container h3:first-of-type,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.2);
  font-weight: 600;
  color: var(--text-color-main);
  letter-spacing: 0.1em;
  white-space: nowrap;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content > h3::before,
.drawer-content
  .flex-container
  h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
.drawer-content .flex-container .flex-container h3:first-of-type::before,
.popup h3:not(dialog *)::before {
  content: "◎";
  position: relative;
  color: var(--chess-white);
  font-size: calc(var(--mainFontSize) * 1.3);
  text-shadow: 0 0 6px rgba(215, 212, 208, 0.3);
  padding-bottom: 0.5px;
  margin-right: 4px;
}

@supports (-webkit-touch-callout: none) {
  .standoutHeader strong::before,
  #right-nav-panel h2::before,
  .drawer-content > h3::before,
  .drawer-content
    .flex-container
    h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
  .drawer-content .flex-container .flex-container h3:first-of-type::before,
  .popup h3:not(dialog *)::before {
    font-size: calc(var(--mainFontSize) * 1.7);
  }
}

/* 增加标题下横线 */
.standoutHeader:not(h4),
#rm_PinAndTabs,
#top-settings-holder
  .drawer:not(:first-child):not(:last-child)
  .drawer-content
  .alignItemsBaseline.wide100p,
#rm_api_block .flex-container.alignItemsBaseline,
#title_api,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup *),
#user-settings-block div[name="userSettingsRowOne"],
#rm_extensions_block
  .alignitemscenter.flex-container.wide100p:not(.justifyCenter) {
  background-image: none;
  border-radius: 0;
  border: none;
  border-bottom: 1px solid var(--chess-line);
  margin-bottom: calc(var(--mainFontSize) * 0.4);
  padding-bottom: calc(var(--mainFontSize) * 0.2);
}

/* 修正标题没对齐的问题 */
.drawer-content .alignItemsBaseline {
  align-items: center !important;
}

#title_api {
  padding-bottom: 0;
}

#title_api::before,
#Backgrounds h3.margin0.flex2::before,
#rm_extensions_block .margin0.flex1::before,
#rm_button_selected_ch h2::before {
  margin-right: calc(var(--mainFontSize) * 0.4);
}

/* ---抽屉--- */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *) {
  border-width: 0 0 0 3px !important;
  border-color: transparent !important;
  border-style: solid;
  border-radius: 0;
  background-image: none !important;
  padding-left: 7px;
  border-image: linear-gradient(
      to bottom,
      transparent 25%,
      var(--chess-white) 25%,
      var(--chess-white) 75%,
      transparent 75%
    )
    1 100%;
}

.inline-drawer-icon {
  font-size: var(--icon-size);
}

/* ---滚动条--- */
::-webkit-scrollbar {
  width: var(--scroll-width);
}

::-webkit-scrollbar:horizontal {
  height: var(--scroll-width);
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
  background-color: color-mix(in srgb, var(--chess-gray) 70%, transparent);
  box-shadow: none;
  border: 0;
}

/* ---输入框--- */
input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]) {
  background-color: var(--ui-color-sec) !important;
  border: 1px solid var(--ui-color-sec) !important;
}

input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):focus {
  border: 1px solid var(--chess-white) !important;
}

textarea[type="search"] {
  background-color: transparent !important;
  border: none !important;
}

.range-block {
  margin: calc(var(--mainFontSize) * 0.6) 0;
}

.range-block-counter {
  margin-left: 20px;
}

.text_pole:not(.objective-task) {
  background-color: var(--ui-color-sec);
  border: none;
}

/* ---按键--- */
.menu_button:not(.mes_edit_buttons *) {
  background-color: var(--ui-color-sec);
  border-color: var(--ui-color-sec);
  color: var(--text-color-main);
}

.menu_button_icon i {
  font-size: calc(var(--icon-size) * 0.8);
}

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG,
.red_button {
  background-color: var(--crimson70a) !important;
  color: var(--white100) !important;
}

#openai_api-presets .title_restorable.standoutHeader .flex-container.gap3px {
  align-items: center;
}

#openai_api-presets
  .title_restorable.standoutHeader
  .flex-container.gap3px
  div:not(label) {
  margin: 5px 0;
}

.mes_button,
.mes_edit_buttons,
#completion_prompt_manager
  #completion_prompt_manager_list
  li.completion_prompt_manager_prompt
  span
  span
  span {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  font-size: var(--icon-size);
  text-shadow: none !important;
}

/* ---下拉框--- */
select {
  background-color: var(--ui-color-sec) !important;
  color: var(--text-color-main);
  border: none !important;
  margin: calc(var(--mainFontSize) * 0.3) 0 !important;
}

select option:not(:checked) {
  color: var(--text-color-sec);
}

select option:checked {
  color: var(--ui-color-sec);
  background-color: var(--text-color-main) !important;
}

select option {
  background-color: var(--ui-color-sec) !important;
}

.ui-widget-content .ui-state-active {
  color: var(--chess-white) !important;
}

/* ---勾选框--- */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  outline: none;
  background-color: var(--ui-color-main);
  filter: none;
  box-shadow: 0 0 0 1px var(--text-color-sec);
  transform: translateY(0);
  margin-left: 1px;
}

input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--chess-white);
}

input[type="checkbox"].del_checkbox {
  margin-right: 0;
}

/* ---滑动条--- */
input[type="range"] {
  box-shadow: none;
  background-color: var(--ui-color-sec) !important;
}

input[type="range"]:hover {
  background-color: color-mix(
    in srgb,
    var(--ui-color-sec) 70%,
    white 10%
  ) !important;
}

input[type="range"]::-webkit-slider-thumb {
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--chess-white) 30%, transparent);
  background-color: var(--chess-white);
  width: 10px;
  height: 10px;
}

.neo-range-slider {
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.1) !important;
}

/* ---盒子--- */
#left-nav-panel,
#right-nav-panel,
#character_popup,
#dialogue_popup,
#chat,
.draggable,
#select_chat_popup,
.popup:not(.transparent_dialogue_popup),
.drawer-content {
  padding: var(--spacing-long);
  background-color: var(--ui-color-main);
  border-radius: var(--box-border-radius);
  border: none;
}

#dialogue_popup_text {
  padding: 0 var(--spacing-long) 0 0;
}

#left-nav-panel,
#right-nav-panel {
  top: var(--top-distance);
  height: 100dvh !important;
  max-height: calc(100dvh - var(--top-distance) - var(--bottom-distance) - 1px);
}

@media screen and (max-width: 1000px) {
  #left-nav-panel,
  #right-nav-panel,
  .drawer-content {
    margin-top: var(--top-distance);
  }

  #left-nav-panel,
  #right-nav-panel {
    height: calc(100dvh - 45px) !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  }
}

/* ---列表--- */
.list-group,
.options-content {
  border: none;
  border-radius: var(--border-radius-small);
  background-color: var(--ui-color-sec) !important;
}

#options {
  background-color: transparent !important;
  padding: 0;
}

.fa-fw:not(#qr--modal-icon) {
  width: auto;
}

#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: var(--icon-size);
}

.avatar img,
body.big-avatars .avatar img {
  box-shadow: none;
  border: none;
}

/* ---代码块--- */
code {
  margin: 0;
  border: none;
  background-color: var(--code-color);
}

body[data-stscript-style] .hljs.language-stscript,
.hljs {
  background: var(--code-color);
}

.custom-mermaid {
  background-color: var(--code-color);
}

.standoutHeader.inline-drawer-header {
  padding: 5px 0;
}

/* ！！！---局部---！！！ */

/* ---顶栏--- */
body.no-blur #top-bar,
#top-bar {
  border-radius: var(--border-radius-small) var(--border-radius-small) 0 0;
  box-shadow: none;
  background-color: transparent !important;
}

body.waifuMode #top-bar {
  border: none;
}

#top-settings-holder {
  top: var(--top-distance);
  box-shadow: 0 2px 0 0 var(--chess-white);
}

#top-settings-holder > :first-child {
  border-radius: var(--box-border-radius) 0 0 0;
}

#top-settings-holder > :last-child {
  border-radius: 0 var(--box-border-radius) 0 0;
}

.drawer {
  color: var(--top-bar-icon-color);
  background-color: var(--top-bar-color);
}

.drawer:has(.openDrawer) {
  background-color: var(--ui-color-main);
}

.drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
}

@supports (-webkit-touch-callout: none) {
  .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
    max-width: 100dvw;
    top: var(--topBarBlockSize);
  }
}
@supports (-webkit-touch-callout: none) {
  @media screen and (min-width: 1000px) {
    #character_popup,
    #world_popup,
    .drawer-content {
      margin-top: 0px;
    }
    #top-settings-holder .drawer .drawer-content {
      right: 0;
      left: 0;
      width: var(--sheldWidth);
    }
    #left-nav-panel,
    #right-nav-panel {
      margin: 0 auto;
      top: calc(var(--topBarBlockSize) + var(--top-distance));
      max-height: calc(
        100dvh - var(--topBarBlockSize) - var(--bottomFormBlockSize)
      );
      border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
      border-bottom: 1px solid var(--chess-white);
    }
  }
}

.drawer-icon {
  opacity: 0.4;
  font-size: calc(var(--icon-size) * 1.1);
  text-shadow: none !important;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
  opacity: 1;
  color: var(--chess-white);
}

.drawer-content {
  box-shadow: 0 2px 0 var(--chess-white);
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
}

.drawer-content h4 {
  font-weight: 600;
}

#AdvancedFormatting h3.flex-container {
  flex-wrap: nowrap;
}

#user-settings-block-content,
#AdvancedFormatting .flex-container.spaceEvenly {
  gap: 10px;
}

.reverse_proxy_warning {
  border: 1px solid var(--ui-color-sec) !important;
  background-color: transparent !important;
}

/* ---聊天界面--- */
#sheld {
  top: calc(var(--topBarBlockSize) + var(--top-distance));
  height: calc(100dvh - var(--topBarBlockSize) - var(--top-distance) - 1px);
}

#chat {
  overflow-y: scroll;
  align-items: center;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  padding: calc(var(--scroll-width) + 4px) 0 var(--scroll-width)
    var(--scroll-width);
  border-radius: 0 0 var(--box-border-radius) var(--box-border-radius);
  background-color: var(--chat-background-color);
}

@supports (-webkit-touch-callout: none) {
  #chat {
    padding-right: var(--scroll-width);
  }
}

.mesAvatarWrapper {
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.mesAvatarWrapper .avatar {
  margin: calc(var(--mainFontSize)) 0 calc(var(--mainFontSize) * 0.4) 0;
}

.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 20%;  
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: contents;
  color: var(--text-color-sec);
}

#chat .ch_name {
  position: relative;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--chess-line);
}

.mes {
  width: var(--mes-width);
  flex-direction: column;
  align-items: center;
  border: none !important;
  background-color: var(--ui-color-main) !important;
  margin: 0;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
}

.mes_block {
  width: var(--mes-block-width);
  padding-left: 0;
}

.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

.last_mes .swipeRightBlock {
  margin: 0 var(--spacing-long) 0 0;
}

/* === 黑白棋子 · 夜间专属 === */

/* 用户消息 - 白棋（夜间发光） */
div[is_user="true"] {
  background-color: rgba(42, 40, 38, 0.95) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: 0 0 0 2px rgba(215, 212, 208, 0.6),
    0 0 12px 3px rgba(215, 212, 208, 0.15),
    0 0 20px 6px rgba(215, 212, 208, 0.05) !important;
  }

/* AI消息 - 黑棋（夜间深沉） */
div[is_user="false"] {
  background-color: rgba(32, 31, 29, 0.95) !important;
}

div[is_user="false"] .avatar img {
  box-shadow: 0 0 0 2px rgba(90, 88, 86, 0.5),
    0 0 8px 2px rgba(0, 0, 0, 0.4) !important;
}

.swipe_left {
  left: calc(var(--scroll-width) + var(--spacing-short));
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

.swipes-counter {
  margin-bottom: 4px;
}

#chat .mes.selected {
  background-color: var(--crimson70a) !important;
}

/* 文档模式 */
body.documentstyle #chat .ch_name::after {
  width: 0;
}

body.documentstyle #chat .mes .mes_block {
  margin-right: 0;
  padding-bottom: 15px;
}

body.documentstyle #chat .last_mes .mes_block {
  padding-bottom: 50px;
}

body.documentstyle #chat .last_mes {
  padding-top: var(--border-radius-medium);
}

body.documentstyle #chat .mes_text {
  margin-left: 0 !important;
}

body.documentstyle #chat .last_mes .swipe_left {
  left: var(--scroll-width);
}

body.waifuMode #chat {
  border: none;
  box-shadow: none;
  border-radius: var(--border-radius-small);
}

body.waifuMode .zoomed_avatar {
  top: 70px;
}

/* 推理块 - 夜间发光边框 */
.mes_reasoning_header {
  margin: 1em 0;
  padding: 7px calc(var(--mainFontSize) + 14px) 7px
    calc(var(--mainFontSize) * 0.8);
  background: rgba(215, 212, 208, 0.04);
  border: 1px solid rgba(215, 212, 208, 0.12);
  color: var(--text-color-main);
}

.mes_reasoning_header span::before {
  content: "◉";
  position: relative;
  text-shadow: 0 0 4px rgba(215, 212, 208, 0.3);
  font-size: var(--mainFontSize);
  line-height: 1;
  margin-right: 3px;
}
.mes_reasoning_details .mes_reasoning_arrow {
  right: 10px;
  font-size: calc(var(--mainFontSize) * 0.7) !important;
}

.mes_reasoning {
  border-left: 2px solid var(--chess-white);
}

/* ---提示词管理器--- */
#left-nav-panel {
  width: calc((100vw - var(--sheldWidth)) / 2 - var(--leftRight-chat-spacing));
  padding-right: 0;
}

@supports (-webkit-touch-callout: none) {
  @media screen and (min-width: 1000px) {
    #left-nav-panel {
      padding-right: var(--spacing-long);
    }
    .fillLeft .scrollableInner {
      padding-right: 0.5em;
    }
  }
}

#range_block_openai > .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div,
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 5px;
}

#completion_prompt_manager {
  width: 100%;
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--text-color-main);
  padding: 0;
}

.completion_prompt_manager_footer {
  padding: 0 !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

#completion_prompt_manager
  #completion_prompt_manager_list
  li.completion_prompt_manager_prompt {
  border-radius: var(--border-radius-medium);
  border-color: var(--white20a);
  background-color: var(--ui-color-main);
}

#completion_prompt_manager
  #completion_prompt_manager_list
  li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager
  #completion_prompt_manager_list
  li.completion_prompt_manager_prompt:focus {
  box-shadow: 0 0 12px rgba(215, 212, 208, 0.06);
  border-color: var(--chess-white);
  background-color: rgba(215, 212, 208, 0.05);
  outline: none;
}

#completion_prompt_manager
  #completion_prompt_manager_list
  .completion_prompt_manager_prompt:not(
    .completion_prompt_manager_prompt_disabled
  )
  .prompt-manager-toggle-action {
  color: var(--chess-white);
}

#completion_prompt_manager
  #completion_prompt_manager_list
  .completion_prompt_manager_prompt_disabled
  .completion_prompt_manager_prompt_name
  .prompt-manager-inspect-action,
#completion_prompt_manager
  #completion_prompt_manager_list
  .completion_prompt_manager_prompt
  .completion_prompt_manager_prompt_name
  .fa-solid {
  color: color-mix(in srgb, var(--text-color-main) 30%, transparent);
}

#completion_prompt_manager > .range-block > .text_pole {
  padding: 0 15px 10px 15px;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}

/* ---世界书--- */
#WorldInfo {
  margin-top: var(--top-distance);
}

@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

#WorldInfo .select2 {
  margin-top: 5px;
}

.world_entry {
  margin-top: var(--spacing-short);
}

.wi-card-entry {
  border: none;
}

.world_entry_form_control {
  margin: 0;
}

.select2-container .select2-selection--multiple {
  background-color: var(--ui-color-sec);
  border: none;
}

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background-color: rgba(215, 212, 208, 0.08);
}

span.select2.select2-container .select2-selection__choice__remove,
.select2_choice_clickable_buttonstyle
  + span.select2-container
  .select2-selection__choice__display {
  color: var(--text-color-main);
  line-height: 1.5;
  background-color: transparent;
  margin: 0px;
}

.select2-container
  .select2-selection--multiple
  .select2-selection__choice__remove {
  padding: 0 5px;
}

@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header {
    border-width: 0 0 0 3px !important;
    border-color: var(--chess-white) !important;
    border-style: solid;
    border-image: none;
  }
}

/* ---用户管理器--- */
.avatar-container.selected {
  border-color: var(--chess-white);
}

/* ---图库--- */
#bg-header-fixed {
  padding: 0;
}

#bg-header-fixed .flex-container.alignItemsBaseline.wide100p {
  margin-bottom: 0 !important;
}

#bg-header-title::before {
  margin-right: var(--spacing-short);
}

#Backgrounds.drawer-content.openDrawer.bg-drawer-layout {
  padding: var(--spacing-long);
}

.bg_example {
  box-shadow: none;
  border-color: var(--ui-color-sec);
}

.bg_example.selected {
  border-color: var(--chess-white);
}

.bg_button {
  color: var(--chess-white);
  filter: drop-shadow(0px 0px 2px black);
}

.bg_button:hover {
  background-color: var(--crimson70a);
}

.BGSampleTitle {
  color: #eeeeee !important;
}

#movingUIPresets {
  margin-bottom: 0 !important;
}

/* ---角色管理器--- */
#right-nav-panel {
  width: calc((100vw - var(--sheldWidth)) / 2 - var(--leftRight-chat-spacing));
}

#right-nav-panel hr:first-of-type {
  display: none;
}

#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.8);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select,
.bogus_folder_select {
  margin-top: calc(var(--mainFontSize) * 0.8);
}

.character_select.is_fav .avatar {
  outline: 2px solid var(--chess-white);
}

.character_select.is_fav .ch_name {
  color: var(--chess-white);
}

.tag.excluded::after {
  font-size: calc(var(--icon-size) * 2);
}

.tag.actionable {
  font-size: calc(var(--icon-size) * 1);
  min-height: calc(var(--icon-size) * 2);
  min-width: calc(var(--icon-size) * 2);
}

#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden;
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + var(--scroll-width) + 10px);
  max-height: calc(var(--avatar-base-height) * 2);
}
body.big-avatars #HotSwapWrapper > div {
  height: calc(
    var(--avatar-base-height) * var(--big-avatar-height-factor) +
      var(--scroll-width) + 10px
  );
  max-height: calc(
    var(--avatar-base-height) * var(--big-avatar-height-factor) * 2
  );
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--ui-color-sec);
}

/* ---底栏：白棋风格发送框--- */
#form_sheld {
  margin: var(--chat-send-spacing) auto var(--bottom-distance) auto;
}

body.no-blur #send_form,
#send_form {
  background-color: rgba(215, 212, 208, 0.12) !important;
  border: 2px solid rgba(215, 212, 208, 0.25) !important;
  border-radius: 30px !important;
  padding: 4px 6px !important;
  backdrop-filter: none;
}

#send_form textarea {
  background-color: transparent !important;
  color: var(--chess-white) !important;
}

#send_form textarea::placeholder {
  color: rgba(215, 212, 208, 0.35) !important;
}

#send_form .fa-solid,
#send_form i,
#leftSendForm i,
#rightSendForm i {
  color: var(--chess-white) !important;
  text-shadow: none;
}

/* QR */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
  background-color: rgba(215, 212, 208, 0.08);
  border-color: rgba(215, 212, 208, 0.2) !important;
  border-radius: var(--border-radius-small) !important;
  border-width: 0 0 0px 0 !important;
  font-size: calc(var(--mainFontSize) * 0.9);
}

#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
  background-color: rgba(215, 212, 208, 0.15) !important;
}

#qr--popoutTrigger {
  background-color: transparent;
  border: none;
}

/* ---QR编辑器--- */
.popup:has(#qr--modalEditor)
  .popup-content
  > #qr--modalEditor
  > #qr--main
  > .qr--modal-messageContainer
  > #qr--modal-messageHolder
  > #qr--modal-message {
  color: var(--text-color-main) !important;
}

.popup:has(#qr--modalEditor) .popup-content #qr--modal-message::selection {
  color: var(--text-color-main) !important;
}

@supports (color: rgb(from white r g b / 0.25)) {
  .popup:has(#qr--modalEditor) .popup-content #qr--modal-message::selection {
    background-color: rgb(from var(--chess-white) r g b / 0.25) !important;
  }
}

/* === 黑白棋子 · 夜间 专属装饰 === */

/* 头像：大尺寸圆角矩形 */
.mesAvatarWrapper {
  width: 100%!important;
  pointer-events: none !important;
}

.mesAvatarWrapper .avatar {
  width: 100% !important;
  height: 220px !important;
  flex: 0 0 auto !important;
  position: relative;
}

.mesAvatarWrapper .avatar img {
  border-radius: 12px !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
}

body.rounded-avatars .avatar,
body.rounded-avatars .avatar img {
  border-radius: 12px !important;
}

/*⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️⚪️🔲⚪️⚪️🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲🔲*/
/* 角色头像定位 */
div[is_user="false"] .mesAvatarWrapper .avatar img {
  object-position: 50% 20%;
}

/* 用户头像定位 */
div[is_user="true"] .mesAvatarWrapper .avatar img {
  object-position: 50% 20%;
}

/* 顶栏图标：白棋符号 ○ */
.drawer-icon {
  opacity: 1 !important;
  color: var(--chess-white) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  -webkit-text-fill-color: unset !important;
}

.drawer-icon:not(.openIcon) {
  font-size: 0 !important;
}

.drawer-icon:not(.openIcon)::after {
  content: "○";
  font-size: calc(var(--icon-size) * 1.3);
  color: var(--chess-white);
  text-shadow: 0 0 6px rgba(215, 212, 208, 0.2);
}

.drawer-icon.openIcon {
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  color: var(--chess-white) !important;
  -webkit-text-fill-color: var(--chess-white) !important;
}

/* 引用文本 - 微妙棋格纹理 */
.mes_text q {
  display: inline;
  background-color: rgba(215, 212, 208, 0.06);
  background-image: 
    linear-gradient(45deg, rgba(215,212,208,0.04) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(215,212,208,0.04) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(215,212,208,0.04) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(215,212,208,0.04) 75%);
  background-size: 8px 8px;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0;
  border-radius: 4px;
  padding: 2px 6px;
  border-left: none !important;
  margin: 0.3em 0;
  color: var(--text-color-main);
}

/* 代码块装饰 - 暗色 */
code {
  background-color: rgba(18, 17, 16, 0.8) !important;
  color: #d7d4d0;
  border-radius: 3px;
  padding: 1px 5px;
}

.hljs {
  background: rgba(18, 17, 16, 0.8) !important;
  color: #d7d4d0;
  border-left: 3px solid rgba(215, 212, 208, 0.3);
  border-radius: 6px;
  padding: 12px 16px !important;
}

pre {
  background-color: rgba(18, 17, 16, 0.8) !important;
  border-radius: 6px;
}

.hljs-keyword, .hljs-selector-tag, .hljs-built_in { color: #bbb; font-weight: 600; }
.hljs-string, .hljs-attr { color: #999; }
.hljs-comment { color: #666; font-style: italic; }
.hljs-function, .hljs-title { color: #ccc; }
.hljs-number, .hljs-literal { color: #aaa; }
.hljs-property, .hljs-variable { color: #b5b5b5; }

/* 消息之间的分隔 */
.mes + .mes {
  border-top: 1px solid var(--chess-line) !important;
}

/* 小白x图标替换 */
.xiaobaix-collapse-btn .xiaobaix-xstack span {
    display: none !important;
}

.xiaobaix-collapse-btn .xiaobaix-xstack::before {
    content: "○";
    color: var(--chess-white);
    font-size: 16px;
    opacity: 0.5;
    font-weight: 100;
    line-height: 1;
}

.xiaobaix-collapse-btn {
    background: transparent !important;
    border: none !important;
}

/* QR栏悬停显隐 */
#qr--bar {
  height: 0;
  overflow: hidden;
  opacity: 0;
  transition: height 0.4s ease, opacity 0.3s ease;
  pointer-events: none;
}

#send_form:hover #qr--bar,
#qr--bar:hover {
  height: auto;
  opacity: 1;
  pointer-events: auto;
}

/* === 夜间独家创意：棋子星光呼吸效果 === */
/* 用户消息微弱的白棋光晕脉动 */
div[is_user="true"] {
  animation: whiteStoneGlow 6s ease-in-out infinite;
}

@keyframes whiteStoneGlow {
  0%, 100% { box-shadow: inset 0 0 20px rgba(215, 212, 208, 0.02); }
  50% { box-shadow: inset 0 0 30px rgba(215, 212, 208, 0.05); }
}

/* AI消息微弱的暗影脉动 */
div[is_user="false"] {
  animation: blackStoneShadow 8s ease-in-out infinite;
}

@keyframes blackStoneShadow {
  0%, 100% { box-shadow: inset 0 0 15px rgba(0, 0, 0, 0.1); }
  50% { box-shadow: inset 0 0 25px rgba(0, 0, 0, 0.2); }
}

/* 名称标签使用棋子装饰 */
#chat .ch_name .name_text::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 6px;
  vertical-align: middle;
}

div[is_user="true"] .ch_name .name_text::before {
  background: var(--chess-white);
  box-shadow: 0 0 4px rgba(215, 212, 208, 0.3);
}

div[is_user="false"] .ch_name .name_text::before {
  background: var(--chess-black);
  box-shadow: 0 0 0 1.5px var(--chess-gray);
}
